const res = await api.get('/mails', {});
const mails = res.items;
if (!mails || mails.length === 0) throw new Error('메일이 없습니다');
// find most recent by received_at
let latest = mails[0];
for (const m of mails) {
  if (new Date(m.received_at) > new Date(latest.received_at)) latest = m;
}
return latest.from_email;

